1	//! `plan_zooms`, Auto Zoom's planner (spec §11 CU-70…CU-75): the selected
2	//! clips' cursor files read into anchors, planned as visits by
3	//! `cursor_zoom_visits.rs`, moved onto clips and answered as ops — every
4	//! `remove_action` (Replace), then every `set_video`, then every
5	//! `add_zoom_action` in time order — that the app applies as ONE undo step.
6	//! Nothing here edits; the plan is checked against the project as it will
7	//! be at apply, so no op refuses there.
8	//!
9	//! **Runs (CU-74).** Clips on one track, each touching the one before, of
10	//! one media, forward, each continuing the other's source — the halves of a
11	//! split — are one run, formed over the whole track. The rest placement is
12	//! the run's first clip's base `scale`, `x`, `y`, and every zoom back ends
13	//! there. Planned actions land only on given clips and never straddle a
14	//! cut; a hold across a cut into a given clip sets its base to the
15	//! placement in force, or, when that clip was not given or has a kept
16	//! action meeting the hold, the cut is a barrier the visit closes at.
17	
18	use serde::Deserialize;
19	use serde_json::{json, Value};
20	
21	use crate::action_class::{is_zoom, moves};
22	use crate::cursor_track::CursorTrack;
23	use crate::cursor_zoom_run::{base, end, media_in, run_of, Run};
24	use crate::cursor_zoom_visits::{self as visits, Planned, Timing};
25	use crate::edit_action::overlapping_action;
26	use crate::edit_zoom::{region_size, ZoomFit, ZoomRegion};
27	use crate::model::{Clip, Project, Source};
28	use crate::time::{seconds_to_ticks, Ticks};
29	
30	/// A rest placement equal to a base, each number to this.
31	const SAME: f64 = 1e-9;
32	/// A run's rest scale may sit this far under the fit before it is placed.
33	const PLACED_TOLERANCE: f64 = 0.001;
34	
35	/// A base's `scale`, `x`, `y`.
36	type Placement = (f64, f64, f64);
37	
38	fn default_zoom() -> f64 {
39	    2.0
40	}
41	fn default_lead() -> f64 {
42	    0.6
43	}
44	fn default_stay() -> f64 {
45	    2.5
46	}
47	fn yes() -> bool {
48	    true
49	}
50	
51	/// `plan_zooms`' request (CU-70's defaults); `lead` and `stay` in seconds,
52	/// `from` and `to` container ticks.
53	#[derive(Deserialize)]
54	#[serde(deny_unknown_fields)]
55	pub(crate) struct PlanZoomsArgs {
56	    #[serde(default)]
57	    pub clips: Vec<u32>,
58	    #[serde(default = "default_zoom")]
59	    pub zoom: f64,
60	    #[serde(default = "default_lead")]
61	    pub lead: f64,
62	    #[serde(default = "default_stay")]
63	    pub stay: f64,
64	    #[serde(default = "yes")]
65	    pub follow: bool,
66	    #[serde(default = "yes")]
67	    pub typing: bool,
68	    #[serde(default)]
69	    pub replace: bool,
70	    #[serde(default)]
71	    pub from: Option<Ticks>,
72	    #[serde(default)]
73	    pub to: Option<Ticks>,
74	}
75	
76	fn in_range(name: &str, unit: &str, v: f64, lo: f64, hi: f64) -> Result<(), String> {
77	    if v.is_finite() && (lo..=hi).contains(&v) {
78	        return Ok(());
79	    }
80	    Err(format!("{name} is {v}{unit}; it runs {lo}–{hi}"))
81	}
82	
83	fn placement(clip: &Clip) -> Placement {
84	    let v = base(clip);
85	    (v.scale, v.x, v.y)
86	}
87	
88	fn same(a: Placement, b: Placement) -> bool {
89	    (a.0 - b.0).abs() <= SAME && (a.1 - b.1).abs() <= SAME && (a.2 - b.2).abs() <= SAME
90	}
91	
92	/// Checks every clip in CU-75's order; answers each clip's run.
93	fn check<'p>(project: &'p Project, clips: &[u32]) -> Result<Vec<Vec<&'p Clip>>, String> {
94	    let mut runs = Vec::new();
95	    for (i, &id) in clips.iter().enumerate() {
96	        if clips[..i].contains(&id) {
97	            return Err(format!("clip {id} is named twice"));
98	        }
99	        let clip = project.require_clip(id)?;
100	        let Source::Media {
101	            media, reversed, ..
102	        } = &clip.source
103	        else {
104	            return Err(format!("clip {id} is not a media clip"));
105	        };
106	        let found = project.media(*media);
107	        if found.and_then(|m| m.cursor.as_ref()).is_none() {
108	            return Err(format!("clip {id}'s media {media} has no cursor file"));
109	        }
110	        if *reversed {
111	            return Err(format!(
112	                "clip {id} plays reversed; Auto Zoom plans only clips that play forward"
113	            ));
114	        }
115	        let picture = clip.video.is_some() && found.is_some_and(|m| m.has_video);
116	        let Some((sw, sh)) = project.source_size(clip).filter(|_| picture) else {
117	            return Err(format!("clip {id} has no picture"));
118	        };
119	        let run = run_of(project, clip);
120	        let rest = run.first().map_or(1.0, |c| base(c).scale);
121	        if rest < project.fit_scale(sw, sh) * (1.0 - PLACED_TOLERANCE) {
122	            return Err(format!(
123	                "clip {id} is placed smaller than the canvas; a zoom would fill the canvas. \
124	                 Nest it (Clip ▸ Nest) and run Auto Zoom inside the nest."
125	            ));
126	        }
127	        runs.push(run);
128	    }
129	    Ok(runs)
130	}
131	
132	/// Answers `plan_zooms` (CU-70…CU-75) against `tracks`, one per clip.
133	pub(crate) fn plan_zooms(
134	    tracks: &[&CursorTrack],
135	    project: &Project,
136	    args: PlanZoomsArgs,
137	) -> Result<Value, String> {
138	    in_range("zoom", "", args.zoom, 1.25, 4.0)?;
139	    in_range("lead", " s", args.lead, 0.2, 2.0)?;
140	    in_range("stay", " s", args.stay, 0.5, 10.0)?;
141	    if let (Some(from), Some(to)) = (args.from, args.to) {
142	        if to <= from {
143	            return Err(format!("to ({to}) must be after from ({from})"));
144	        }
145	    }
146	    if args.clips.is_empty() {
147	        return Err("plan_zooms needs at least one clip".into());
148	    }
149	    if tracks.len() != args.clips.len() {
150	        return Err(format!(
151	            "plan_zooms reads one cursor track per clip; {} clips and {} tracks were given",
152	            args.clips.len(),
153	            tracks.len()
154	        ));
155	    }
156	    let runs = check(project, &args.clips)?;
157	    let window = (
158	        args.from.unwrap_or(Ticks::MIN),
159	        args.to.unwrap_or(Ticks::MAX),
160	    );
161	    // CU-71: what Replace removes; `next` is the project as it will be at
