205	            clips: run_clips,
206	            given: &args.clips,
207	            tracks,
208	            next: &next,
209	            window,
210	            typing: args.typing,
211	            half,
212	        };
213	        let frame = run.frame(scale);
214	        let (anchors, bursts) = run.anchors();
215	        let mut barriers = run.barriers();
