318	/// The region in Q for `aim` (in P) on `clip` at clip time `at` of the
319	/// project as it will be at apply: `region_size` at the zoomed scale and the
320	/// evaluated rotation, centred on the aim less the evaluated crop's centre.
321	fn zoom_region(next: &Project, clip: &Clip, at: Ticks, aim: (f64, f64), scale: f64) -> ZoomRegion {
322	    let v = next.evaluate_clip(clip, at).video;
323	    let canvas = (f64::from(next.canvas.width), f64::from(next.canvas.height));
324	    let (width, height) = region_size(canvas, scale, v.rotation);
325	    ZoomRegion {
326	        x: aim.0 - (v.crop.l - v.crop.r) / 2.0,
327	        y: aim.1 - (v.crop.t - v.crop.b) / 2.0,
328	        width,
329	        height,
330	    }
331	}
332	//! A run of Auto Zoom (spec §11 CU-74), cut out of `cursor_zoom.rs` by
333	//! the 400-line rule for a new file: which clips are one run, and what a run
334	//! is planned against — its given clips' anchors and scroll bursts in
335	//! container time (CU-70, CU-72), its barriers, the raw cursor for follow,
336	//! and where a planned span lands (no straddled cut, only given clips).
337	
338	use crate::cursor_bursts::{scroll_bursts, typing_stretches};
339	use crate::cursor_track::{ticks_to_us, us_to_ticks, CursorTrack};
340	use crate::cursor_zoom_visits::{Anchor, Barrier, Frame, Planned};
341	use crate::edit_zoom::region_size;
342	use crate::model::{Clip, Project, Source, VideoProps};
