366	/// Whether `b` continues `a` in one run.
367	pub(crate) fn continues(a: &Clip, b: &Clip) -> bool {
368	    let (Some((ma, _)), Some((mb, ib))) = (media_in(a), media_in(b)) else {
369	        return false;
370	    };
371	    let advanced = match source_advanced_through(a, a.duration) {
372	        Source::Media { r#in, .. } => r#in,
373	        _ => return false,
374	    };
375	    ma == mb && b.start == end(a) && ib == advanced
376	}
