399	/// Clip time for `read` source ticks past `in`: through S on a ramp,
400	/// `⌊read / speed⌋` otherwise.
401	pub(crate) fn clip_time(clip: &Clip, read: Ticks) -> Ticks {
402	    if is_ramped(clip) {
403	        return time_for_source(clip, read).unwrap_or(0);
404	    }
405	    (read as f64 / clip.speed).floor() as Ticks
406	}
