507	    /// Cuts into a clip that was not given, and the run's end.
508	    pub(crate) fn barriers(&self) -> Vec<Barrier> {
509	        let mut out: Vec<Barrier> = self
510	            .clips
511	            .windows(2)
512	            .filter(|w| !self.is_given(w[1]))
513	            .map(|w| Barrier {
514	                at: end(w[0]),
515	                counted: true,
516	            })
517	            .collect();
518	        if let Some(last) = self.clips.last() {
519	            out.push(Barrier {
520	                at: end(last),
521	                counted: false,
522	            });
523	        }
524	        out
525	    }
