527	    /// Cuts a hold crosses into a given clip with a kept action meeting
528	    /// the hold, not yet barriers.
529	    pub(crate) fn closing_cuts(&self, holds: &[(Ticks, Ticks)], have: &[Barrier]) -> Vec<Barrier> {
530	        let mut out: Vec<Barrier> = Vec::new();
531	        for w in self.clips.windows(2) {
532	            let cut = end(w[0]);
533	            if have.iter().chain(&out).any(|b| b.at == cut) {
534	                continue;
535	            }
536	            let Some(after) = self.next.clip(w[1].id) else {
537	                continue;
538	            };
539	            let hit = holds.iter().any(|&(lo, hi)| {
540	                lo < cut
541	                    && cut < hi
542	                    && after.actions.iter().any(|a| {
543	                        let s = after.start.saturating_add(a.start);
544	                        s < hi && cut < s.saturating_add(a.duration)
545	                    })
546	            });
547	            if hit {
548	                out.push(Barrier {
549	                    at: cut,
550	                    counted: true,
551	                });
552	            }
553	        }
554	        out
555	    }
