557	    /// The raw cursor in P at container time `t`, inside a given clip.
558	    pub(crate) fn cursor(&self, t: Ticks) -> Option<(f64, f64)> {
559	        let c = self
560	            .clips
561	            .iter()
562	            .find(|c| self.is_given(c) && c.start <= t && t < end(c))?;
563	        let track = self.track(c)?;
564	        let (_, source_in) = media_in(c)?;
565	        let us = ticks_to_us(source_in.saturating_add(source_read_by(c, t - c.start)));
566	        let (x, y) = track.raw_at(us)?;
567	        let (mx, my) = track.to_movie(us, x, y);
568	        Some((mx - self.half.0, my - self.half.1))
569	    }
