571	    /// CU-74: the given clip a planned span lands on, the span moved so it
572	    /// straddles no cut and held inside the clip.
573	    pub(crate) fn land(&self, mut p: Planned) -> Option<(u32, Planned)> {
574	        let mid = p.from + (p.to - p.from) / 2;
575	        let overlap = |c: &Clip| (p.to.min(end(c)) - p.from.max(c.start)).max(0);
576	        let distance = |c: &Clip| (c.start - p.to).max(p.from - end(c)).max(0);
577	        let target = self
578	            .clips
579	            .iter()
580	            .find(|c| self.is_given(c) && c.start <= mid && mid < end(c))
581	            .or_else(|| {
582	                self.clips
583	                    .iter()
584	                    .filter(|c| self.is_given(c))
585	                    .min_by_key(|c| (-overlap(c), distance(c)))
586	            })?;
587	        let d = p.to - p.from;
588	        if p.from < target.start {
589	            (p.from, p.to) = (target.start, target.start + d);
590	        }
591	        if p.to > end(target) {
592	            (p.from, p.to) = (end(target) - d, end(target));
593	        }
594	        p.from = p.from.max(target.start);
595	        Some((target.id, p))
596	    }
597	}
