193	        };
194	        if heads.contains(&head.id) {
195	            continue;
196	        }
197	        heads.push(head.id);
198	        let rest = placement(head);
199	        let scale = rest.0 * args.zoom;
200	        let media = media_in(head).and_then(|(m, _)| project.media(m));
201	        let half = media.map_or((0.0, 0.0), |m| {
202	            (f64::from(m.width) / 2.0, f64::from(m.height) / 2.0)
