205	            clips: run_clips,
206	            given: &args.clips,
207	            tracks,
208	            next: &next,
209	            window,
210	            typing: args.typing,
211	            half,
212	        };
213	        let frame = run.frame(scale);
214	        let (anchors, bursts) = run.anchors();
215	        let mut barriers = run.barriers();
216	        let plan = loop {
217	            let cursor = |t: Ticks| run.cursor(t);
218	            let plan = visits::plan(anchors.clone(), &bursts, &barriers, timing, frame, &cursor);
219	            let more = run.closing_cuts(&plan.holds, &barriers);
220	            if more.is_empty() {
