227	        closed += plan.closed;
228	        let moved: Vec<(u32, Planned)> = plan.actions.iter().filter_map(|p| run.land(*p)).collect();
229	        let mut run_bases: Vec<(u32, Placement)> = Vec::new();
230	        // CU-74: a hold across a cut into a given clip sets its base.
231	        for w in run.clips.windows(2) {
232	            if !run.is_given(w[1]) {
233	                continue;
234	            }
235	            let cut = end(w[0]);
236	            let in_force = moved
237	                .iter()
238	                .filter(|(_, p)| p.to <= cut)
239	                .max_by_key(|(_, p)| p.to)
