259	        landed.extend(moved.into_iter().map(|(id, p)| (id, p, rest, scale)));
260	        bases.extend(run_bases);
261	    }
262	    for &(id, set) in &bases {
263	        if let Some(v) = next.clip_mut(id).and_then(|c| c.video.as_mut()) {
264	            (v.scale, v.x, v.y) = set;
265	        }
266	    }
267	    landed.sort_by_key(|(_, p, _, _)| p.from);
268	    let mut ops: Vec<Value> = removed
269	        .iter()
270	        .map(|(c, a)| json!({"op": "remove_action", "clip": c, "action": a}))
271	        .collect();
272	    for (id, (scale, x, y)) in &bases {
273	        ops.push(json!({"op": "set_video", "clips": [id],
274	                        "patch": {"scale": scale, "x": x, "y": y}}));
275	    }
276	    let (mut added, mut dropped) = (0, 0);
277	    let mut actions: Vec<Value> = Vec::new();
278	    let mut busy: Vec<(u32, Ticks)> = Vec::new();
279	    for (id, p, rest, scale) in landed {
280	        let clip = next.require_clip(id)?;
281	        let mut at = next.snapped(p.from - clip.start).max(0);
282	        let mut duration = next.snapped(p.to - p.from);
283	        if let Some((_, until)) = busy.iter().find(|(c, _)| *c == id) {
284	            if at < *until {
285	                duration -= until - at;
286	                at = *until;
287	            }
288	        }
289	        duration = duration.min(clip.duration - at);
290	        if duration < next.frame() {
291	            continue;
292	        }
293	        if overlapping_action(&clip.actions, None, at, duration).is_some() {
294	            dropped += 1;
295	            continue;
296	        }
297	        busy.retain(|(c, _)| *c != id);
298	        busy.push((id, at + duration));
299	        let region = match p.aim {
300	            Some(aim) => json!(zoom_region(&next, clip, at, aim, scale)),
301	            None if same(placement(clip), rest) => Value::Null,
302	            None => json!(next.region_for_placement(clip, at, rest)),
303	        };
304	        ops.push(
305	            json!({"op": "add_zoom_action", "clip": id, "at": at, "duration": duration,
306	                        "region": region, "fit": "fit", "curve": "ease_in_out"}),
307	        );
308	        actions.push(json!({"clip": id, "at": at, "duration": duration, "kind": p.kind.name()}));
309	        added += 1;
310	    }
311	    Ok(json!({
312	        "ops": ops, "visits": visit_count, "added": added, "replaced": removed.len(),
313	        "dropped": dropped, "closed_at_cut": closed, "bases_set": bases.len(),
314	        "actions": actions,
315	    }))
316	}
