347	pub(crate) fn base(clip: &Clip) -> VideoProps {
348	    clip.video.clone().unwrap_or_default()
349	}
350	
351	pub(crate) fn end(c: &Clip) -> Ticks {
352	    c.start.saturating_add(c.duration)
353	}
354	
355	pub(crate) fn media_in(clip: &Clip) -> Option<(u32, Ticks)> {
356	    match &clip.source {
357	        Source::Media {
358	            media,
359	            r#in,
360	            reversed: false,
361	        } => Some((*media, *r#in)),
362	        _ => None,
363	    }
364	}
