378	/// The run `clip` is in, in time order.
379	pub(crate) fn run_of<'p>(project: &'p Project, clip: &Clip) -> Vec<&'p Clip> {
380	    let mut on: Vec<&Clip> = project
381	        .clips
382	        .iter()
383	        .filter(|c| c.track == clip.track)
384	        .collect();
385	    on.sort_by_key(|c| c.start);
386	    let Some(at) = on.iter().position(|c| c.id == clip.id) else {
387	        return Vec::new();
388	    };
389	    let (mut lo, mut hi) = (at, at);
390	    while lo > 0 && continues(on[lo - 1], on[lo]) {
391	        lo -= 1;
392	    }
393	    while hi + 1 < on.len() && continues(on[hi], on[hi + 1]) {
394	        hi += 1;
395	    }
396	    on[lo..=hi].to_vec()
397	}
