408	/// What a run is planned against.
409	pub(crate) struct Run<'a> {
410	    pub clips: Vec<&'a Clip>,
411	    pub given: &'a [u32],
412	    pub tracks: &'a [&'a CursorTrack],
413	    /// The project as it will be at apply (Replace's removals made).
414	    pub next: &'a Project,
415	    pub window: (Ticks, Ticks),
416	    pub typing: bool,
417	    /// Half the media's size, P's origin in movie px.
418	    pub half: (f64, f64),
419	}
420	
421	impl Run<'_> {
422	    pub(crate) fn is_given(&self, c: &Clip) -> bool {
423	        self.given.contains(&c.id)
424	    }
425	
426	    fn track(&self, c: &Clip) -> Option<&CursorTrack> {
427	        let i = self.given.iter().position(|&g| g == c.id)?;
428	        self.tracks.get(i).copied()
429	    }
430	
431	    fn p(&self, track: &CursorTrack, t_us: f64, x: i64, y: i64) -> (f64, f64) {
432	        let (mx, my) = track.to_movie(t_us, x as f64, y as f64);
433	        (mx - self.half.0, my - self.half.1)
434	    }
435	
436	    /// The region's size at `scale` and the cropped rect, from the run's
437	    /// first given clip.
438	    pub(crate) fn frame(&self, scale: f64) -> Frame {
439	        let first = self.clips.iter().find(|c| self.is_given(c));
440	        let v = first.map(|c| base(c)).unwrap_or_default();
441	        let canvas = (
442	            f64::from(self.next.canvas.width),
443	            f64::from(self.next.canvas.height),
444	        );
445	        let (hw, hh) = self.half;
446	        Frame {
447	            size: region_size(canvas, scale, v.rotation),
448	            min: (-hw + v.crop.l, -hh + v.crop.t),
449	            max: (hw - v.crop.r, hh - v.crop.b),
450	        }
451	    }
452	
453	    /// Every given clip's anchors (CU-70, CU-72) and scroll-burst starts,
454	    /// in container time.
455	    pub(crate) fn anchors(&self) -> (Vec<Anchor>, Vec<Ticks>) {
456	        let (mut anchors, mut bursts) = (Vec::new(), Vec::new());
457	        for &c in self.clips.iter().filter(|c| self.is_given(c)) {
458	            let (Some(track), Some((_, source_in))) = (self.track(c), media_in(c)) else {
459	                continue;
460	            };
461	            let length = self.next.content_length_in_source(c);
462	            let file = track.file();
463	            let inside = |us: i64| {
464	                let s = us_to_ticks(us);
465	                (source_in <= s && s < source_in.saturating_add(length))
466	                    .then(|| c.start.saturating_add(clip_time(c, s - source_in)))
467	            };
468	            let kept = |t: Ticks| self.window.0 <= t && t < self.window.1;
469	            let k = &file.clicks;
470	            let downs: Vec<usize> = (0..k.t.len()).filter(|&i| k.down[i] == 1).collect();
471	            for &i in &downs {
472	                if let Some(t) = inside(k.t[i]).filter(|&t| kept(t)) {
473	                    let p = self.p(track, k.t[i] as f64, k.x[i], k.y[i]);
474	                    anchors.push(Anchor { t, end: t, p });
475	                }
476	            }
477	            if self.typing {
478	                for (first, last, _) in typing_stretches(&file.keys.typed.t) {
479	                    let Some(t) = inside(first).filter(|&t| kept(t)) else {
480	                        continue;
481	                    };
482	                    let read = us_to_ticks(last) - source_in;
483	                    let until = c.start.saturating_add(clip_time(c, read)).max(t);
484	                    // CU-72: the last down click at or before the first mark.
485	                    let aim = downs.iter().rev().find(|&&i| k.t[i] <= first);
486	                    let p = match aim {
487	                        Some(&i) => self.p(track, k.t[i] as f64, k.x[i], k.y[i]),
488	                        None => match track.raw_at(first as f64) {
489	                            Some((x, y)) => {
490	                                let (mx, my) = track.to_movie(first as f64, x, y);
491	                                (mx - self.half.0, my - self.half.1)
492	                            }
493	                            None => continue,
494	                        },
495	                    };
496	                    anchors.push(Anchor { t, end: until, p });
497	                }
498	            }
499	            for (first, _, _) in scroll_bursts(&file.scrolls.t) {
500	                bursts.extend(inside(first));
501	            }
502	        }
503	        bursts.sort_unstable();
504	        (anchors, bursts)
505	    }
